'use strict';

const BONUS_SOURCE='https://asamblea.gob.sv/node/14127';
function bonusResult(){
 const b=bonusEstimate();
 if(!b.valid)return `<div class="notice amber">${icon('info')}<div>Completa las fechas de trabajo y el salario para revisar el aguinaldo.</div></div>`;
 return `<div class="bonus-result"><div class="bonus-result-head"><span>${icon('calendar')}${b.label}</span><span class="example-chip">ESTIMACIÓN</span></div><p>${b.reason}</p><div class="bonus-amounts"><div><span>Importe estimado</span><strong>${money(b.amount)}</strong></div><div><span>Ya recibido</span><strong>${money(b.paid)}</strong></div><div><span>Pendiente</span><strong>${money(b.pending)}</strong></div></div>${b.paid>b.amount?'<p class="field-help">El pago registrado supera la estimación. El saldo pendiente se muestra en cero; revisa el importe recibido.</p>':''}<div class="calc-box"><div class="calc-head">${icon('coins')}<strong>Cómo se calculó</strong></div><ul><li>Años de servicio: ${b.years} → tramo de <b>${b.salaryDays} días</b> de salario</li><li>Aguinaldo completo: ${money(Number(data.salary))} ÷ 30 × ${b.salaryDays} = <b>${money(b.annualAmount)}</b></li>${b.full?'':`<li>Días trabajados del ${dateLabel(b.from)} al ${dateLabel(b.to)}: ${b.workedPeriod.months} meses × 30 + ${b.workedPeriod.days} días = ${b.workedDays} días</li><li>Proporcional: (${money(b.annualAmount)} ÷ 360) × ${b.workedDays} días = <b>${money(b.amount)}</b></li>`}${b.paid?`<li>Menos lo recibido: ${money(b.paid)} → pendiente <b>${money(b.pending)}</b></li>`:''}</ul><table class="tier-table"><thead><tr><th>Tiempo de servicio</th><th>Días de salario</th></tr></thead><tbody><tr class="${b.salaryDays===15?'on':''}"><td>1 año a menos de 3</td><td>15</td></tr><tr class="${b.salaryDays===19?'on':''}"><td>3 años a menos de 10</td><td>19</td></tr><tr class="${b.salaryDays===21?'on':''}"><td>10 años o más</td><td>21</td></tr></tbody></table><p class="field-help">El aguinaldo no lleva descuentos de ISSS ni AFP. Está exento de renta hasta $1,500${b.amount>1500?'; este importe supera ese límite y el excedente está sujeto a ISR':''}.</p></div></div>`;
}
function stepBonus(){
 const b=bonusEstimate();
 return `<div class="bonus-calendar"><span class="calendar-symbol">${icon('calendar')}</span><div><strong>Pago desde el 1 de octubre hasta el 20 de diciembre</strong><p>Reforma de 2026: si terminaste el 1 de octubre o después (con al menos 1 año), el aguinaldo es completo. Si fue el 30 de septiembre o antes, es proporcional.</p><a href="${BONUS_SOURCE}" target="_blank" rel="noopener noreferrer">Consultar la reforma</a></div></div>${b.valid&&b.year<2026?'<p class="field-help">La fecha ingresada corresponde a un año anterior a esta reforma; la referencia del período de pago se ajusta al año seleccionado.</p>':''}<div class="section-divider"></div><div class="question-box question-card" role="group" aria-labelledby="bonus-paid-label">${questionHeader('bonus-paid-label','¿Ya recibiste algún pago de aguinaldo de este año?','coins')}${yesno('bonusPaid')}${data.bonusPaid==='si'?`<div class="fields conditional" data-reveal="bonus-payment">${field('bonusPaidAmount','Monto recibido (USD)','number','min="0.01" step="0.01" inputmode="decimal"')}${field('bonusPaidDate','Fecha en que lo recibiste','date',`min="${b.valid?b.year+'-01-01':escapeHTML(data.start)}" max="${escapeHTML(data.end)}"`)}</div><p class="field-help">Este importe se resta de la estimación para evitar cobrarlo dos veces.</p>`:''}</div><div id="bonus-result">${bonusResult()}</div><p class="field-help bonus-scope">Referencia para despido sin causa y renuncia voluntaria. El cálculo definitivo debe validar los requisitos del caso y la norma aplicable.</p>`;
}
function monthlyContributions(){
 const salary=Math.max(0,Number(data.salary)||0),isss=Math.round(Math.min(salary,LABOR_REFERENCE.isssMonthlyBaseCap)*LABOR_REFERENCE.isssRate*100)/100,afp=Math.round(salary*LABOR_REFERENCE.afpRate*100)/100;
 return {salary,isss,afp,net:Math.round((salary-isss-afp)*100)/100};
}
function sidebarContributions(){
 const c=monthlyContributions();
 return `<div class="snapshot-contributions"><div class="snapshot-row"><span>ISSS · 3% <small>Tope: $30 / mes</small></span><strong>−${money(c.isss)}</strong></div><div class="snapshot-row"><span>AFP · 7.25% <small>Sin techo salarial</small></span><strong>−${money(c.afp)}</strong></div><div class="snapshot-monthly-net"><span>Salario después de ISSS y AFP</span><strong>${money(c.net)}</strong><small>Referencia mensual · antes de ISR</small></div></div>`;
}
